/**
 * Code emission helpers: literals, identifiers, member access, relative module paths and the
 * "generated by tsv" header. Everything here is pure and deterministic.
 */

const IDENTIFIER = /^[A-Za-z_$][\w$]*$/;

/** Words that cannot be used as a binding name in an ES module. */
const RESERVED: ReadonlySet<string> = new Set(
  (
    "await break case catch class const continue debugger default delete do else enum export " +
    "extends false finally for function if implements import in instanceof interface let new " +
    "null package private protected public return static super switch this throw true try " +
    "typeof var void while with yield arguments eval undefined NaN Infinity"
  ).split(" "),
);

export function isIdentifier(name: string): boolean {
  return IDENTIFIER.test(name) && !RESERVED.has(name);
}

/** An object-literal key: bare when it is an identifier, quoted otherwise. */
export function propertyKey(key: string): string {
  return IDENTIFIER.test(key) ? key : JSON.stringify(key);
}

/** Member access: `.key` or `["key"]`. */
export function member(key: string): string {
  return IDENTIFIER.test(key) ? `.${key}` : `[${JSON.stringify(key)}]`;
}

/** Replaces a value by raw code (e.g. `"$id"` → `ID`); `undefined` keeps the value. */
export type Replacer = (value: unknown) => string | undefined;

/** A single-line JavaScript literal for a JSON-like fixture value. */
export function literal(value: unknown, replace?: Replacer): string {
  const raw = replace?.(value);
  if (raw !== undefined) return raw;
  if (value === null) return "null";
  if (value === undefined) return "undefined";
  if (typeof value === "string") return JSON.stringify(value);
  if (typeof value === "number" || typeof value === "boolean") return String(value);
  if (Array.isArray(value)) return `[${value.map((v) => literal(v, replace)).join(", ")}]`;
  if (typeof value === "object") {
    const entries = Object.entries(value).map(
      ([k, v]) => `${propertyKey(k)}: ${literal(v, replace)}`,
    );
    return entries.length === 0 ? "{}" : `{ ${entries.join(", ")} }`;
  }
  throw new Error(`testgen: unsupported fixture value of type ${typeof value}`);
}

/** Allocates unique binding names for one generated file. */
export class Names {
  private readonly used = new Set<string>();

  constructor(reserved: Iterable<string>) {
    for (const name of reserved) this.used.add(name);
  }

  /** `preferred` (sanitised) if free, else `preferred_2`, `preferred_3`, … */
  allocate(preferred: string): string {
    let base = preferred.replace(/[^\w$]/g, "_");
    if (!/^[A-Za-z_$]/.test(base)) base = `_${base}`;
    let name = base;
    for (let n = 2; this.used.has(name) || RESERVED.has(name); n++) name = `${base}_${n}`;
    this.used.add(name);
    return name;
  }
}

/**
 * A `/`-separated path from directory `fromDir` to file `to`, both relative to the same root
 * (the project root), as an import specifier (`./x` or `../x`). Pure: no `process.cwd()`.
 */
export function relativeImport(fromDir: string, to: string): string {
  const from = segments(fromDir);
  const target = segments(to);
  let common = 0;
  while (common < from.length && common < target.length - 1 && from[common] === target[common]) {
    common++;
  }
  const up = from.slice(common).map(() => "..");
  const rest = target.slice(common);
  const path = [...up, ...rest].join("/");
  return up.length === 0 ? `./${path}` : path;
}

function segments(path: string): string[] {
  const out: string[] = [];
  for (const part of path.replaceAll("\\", "/").split("/")) {
    if (part === "" || part === ".") continue;
    if (part === ".." && out.length > 0 && out.at(-1) !== "..") out.pop();
    else out.push(part);
  }
  return out;
}

export interface HeaderInput {
  /** Spec file, relative to the project root. */
  specFile: string;
  behavior: string;
  /** What the file tests, e.g. `path tests for checkout, refund` or `finding <id>`. */
  source: string[];
}

/** The header every generated file starts with (as `//` comment lines). */
export function headerLines(h: HeaderInput): string[] {
  return [
    `// Generated by tsv — do not edit. \`tsv test\` deletes and rewrites this directory on every run.`,
    `// Spec: ${h.specFile} (behavior "${h.behavior}")`,
    ...h.source.map((line, i) => `// ${i === 0 ? "Source: " : "  "}${line}`),
  ];
}

/** The same header as one string, for the `$comment` key of a JSON sidecar. */
export function headerText(h: HeaderInput): string {
  return [
    "Generated by tsv — do not edit. `tsv test` deletes and rewrites this directory on every run.",
    `Spec: ${h.specFile} (behavior "${h.behavior}").`,
    `Source: ${h.source.join(" ")}`,
  ].join(" ");
}
